// Initialize a new Git repository in a Java project folder
// This creates a hidden .git directory that stores all history
git init my-java-app
cd my-java-app

// Create a simple Java file
echo 'public class App { public static void main(String[] args) { System.out.println("Hello Git"); } }' > App.java

// Stage the file for commit
git add App.java

// Commit to local repository — this records a snapshot
git commit -m "Initial commit with App.java"

// Check the commit history (all stored locally in .git/)
git log --oneline

// Make a change
echo '// Updated' >> App.java
git diff  // Shows changes in working directory vs last commit

// You can do all of this without internet — that's the distributed advantage

// Start with a clean Java project in working directory
public class OrderService {
    public void processOrder(Order order) {
        // Modified business logic
        validateOrder(order);
        saveOrder(order);
    }
    private void validateOrder(Order order) { /* validation */ }
    private void saveOrder(Order order) { /* persistence */ }
}

// git status shows changes in working directory
// Modified:   OrderService.java

// Stage the changes — move from working directory to staging area
git add OrderService.java

// git status now shows changes in staging area
// Changes to be committed: modified OrderService.java

// Commit — move from staging area to local repository
git commit -m "Add order validation logic"

// Now .git/ contains a permanent snapshot of this version

// Commit 1: Initial project state
// Tree: OrderService.java (blob abc123), Order.java (blob def456)
public class OrderService {
    public void processOrder(Order order) {
        System.out.println("Processing");
    }
}

// Make a change and commit
// Commit 2: Modified OrderService.java
public class OrderService {
    public void processOrder(Order order) {
        validateOrder(order);  // Added line
        System.out.println("Processing");
    }
}

// Git stores:
// - New blob xyz789 for modified OrderService.java
// - Reuses blob def456 for unchanged Order.java
// - Commit 2 tree points to: OrderService.java (blob xyz789), Order.java (blob def456)

// Each commit is a complete snapshot of the tree
// Not a diff like: "added line 3 in OrderService.java"
